156	        this.membershipNumber = membershipNumber;
157	    }
158	
159	    /**
160	     * Whether this owner was created as part of a bulk signup: {@code true} when more
161	     * than 80 owners had already been registered on this owner's registration date at
162	     * the moment it was created, {@code false} otherwise. Captured at creation.
163	     */
164	    public boolean isBulkSignupWarning() {
165	        return this.bulkSignupWarning;
166	    }
167	
168	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
169	        this.bulkSignupWarning = bulkSignupWarning;
170	    }
171	
172	    /**
173	     * The owner's locality: the canonical region derived from the city via the fixed
174	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or
175	     * {@code "UNKNOWN"} for any other city. Derived from stored state, never persisted.
176	     */
177	    public String getLocality() {
178	        return CityLocality.forCity(this.city);
179	    }
180	
181	    /**
182	     * The owner's membership level, from 1 to 3: starts at 1, gains 1 when this owner has
183	     * an email address, and gains 1 when this owner had no namesakes at creation
184	     * ({@code namesakeCount} is 0). Capped at 3 (level 4 is reserved for tenure). Derived
185	     * from stored state, never persisted.
186	     */
187	    public int getMembershipLevel() {
188	        int level = 1;
189	        if (hasEmail()) {
190	            level++;
191	        }
192	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
193	            level++;
194	        }
195	        return Math.min(level, 3);
196	    }
197	
198	    /**
199	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
200	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
201	     */
202	    public String getContactPreference() {
203	        return hasEmail() ? "EMAIL" : "PHONE";
204	    }
205	
206	    /**
207	     * The owner's identity key: the single value all duplicate detection is expressed
208	     * through, formed as the normalized telephone, the email (or empty when absent) and
209	     * the household id (or empty when none), joined by {@code '|'}. Two owners are
210	     * duplicates only when their whole identity keys are equal, so members of the same
211	     * household with different telephones have different keys and are all allowed. Derived
212	     * from stored state, never persisted.
213	     */
214	    public String getIdentityKey() {
215	        String emailPart = hasEmail() ? this.email : "";
216	        String householdPart = this.householdId == null ? "" : this.householdId;
217	        return this.telephone + "|" + emailPart + "|" + householdPart;
218	    }
219	
220	    private boolean hasEmail() {
221	        return this.email != null && !this.email.isEmpty();
222	    }
223	
224	    protected Set<Pet> getPetsInternal() {
225	        if (this.pets == null) {
226	            this.pets = new HashSet<>();
227	        }
228	        return this.pets;
229	    }
230	
231	    protected void setPetsInternal(Set<Pet> pets) {
232	        this.pets = pets;
233	    }
234	
235	    public List<Pet> getPets() {
236	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
237	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
238	        return Collections.unmodifiableList(sortedPets);
239	    }
240	
241	    public void setPets(List<Pet> pets) {
242	        this.pets = new HashSet<>(pets);
243	    }
244	
245	    public void addPet(Pet pet) {
246	        getPetsInternal().add(pet);
247	        pet.setOwner(this);
248	    }
249	
250	    /**
251	     * Return the Pet with the given name, or null if none found for this Owner.
252	     *
253	     * @param name to test
254	     * @return true if pet name is already in use
255	     */
256	    public Pet getPet(String name) {
257	        return getPet(name, false);
258	    }
259	
260	    /**
261	     * Return the Pet with the given name, or null if none found for this Owner.
262	     *
263	     * @param name to test
264	     * @return true if pet name is already in use
265	     */
266	    public Pet getPet(String name, boolean ignoreNew) {
267	        name = name.toLowerCase();
268	        for (Pet pet : getPetsInternal()) {
269	            if (!ignoreNew || !pet.isNew()) {
270	                String compName = pet.getName();
271	                compName = compName.toLowerCase();
272	                if (compName.equals(name)) {
273	                    return pet;
274	                }
275	            }
276	        }
277	        return null;
278	    }
279	
280	    public Pet getPet(Integer petId) {
281	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
282	    }
283	
284	    @Override
285	    public String toString() {
286	        return new ToStringCreator(this)
287	
288	            .append("id", this.getId())
289	            .append("new", this.isNew())
290	            .append("lastName", this.getLastName())
291	            .append("firstName", this.getFirstName())
292	            .append("address", this.address)
293	            .append("city", this.city)
294	            .append("telephone", this.telephone)
295	            .toString();
296	    }
297	}
