1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Resolves an owner's locality (the canonical region) from its city using a fixed
7	 * city-to-region table: Sydney->NSW, Melbourne->VIC, Brisbane->QLD.
8	 *
9	 * <p>Cities not in the table have no known region and resolve to {@code "UNKNOWN"}.
10	 */
11	public final class CityLocality {
12	
13	    /** City -> canonical region. Anything not listed resolves to {@link #UNKNOWN}. */
14	    private static final Map<String, String> CITY_REGION = Map.of(
15	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
16	
17	    /** The locality returned for a city with no known region. */
18	    public static final String UNKNOWN = "UNKNOWN";
19	
20	    private CityLocality() {
21	    }
22	
23	    /**
24	     * @param city the owner's city, as stored
25	     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when it is
26	     *         not in the table (including a null city)
27	     */
28	    public static String forCity(String city) {
29	        return CITY_REGION.getOrDefault(city, UNKNOWN);
30	    }
31	}
